// Encryption at rest of an owner private key (P2 on the lawyer node, P3 on sq-mock). AES-256-GCM from Node crypto, no homemade
// cryptography. The secret is bound to its owner by the additional authenticated data, so a row cannot be swapped for another.
// Source of truth: /shared. Copies are generated by `npm run sync-shared`.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const ALGORITHM = "aes-256-gcm";
const TAG_BYTES = 16;

/** Accepts 32 bytes as 64 hex characters or as base64. Throws without echoing the value. */
export function parseEncKey(raw: string | undefined): Buffer {
  if (!raw) throw new Error("Encryption key is not configured");
  const key = /^[0-9a-fA-F]{64}$/.test(raw) ? Buffer.from(raw, "hex") : Buffer.from(raw, "base64");
  if (key.length !== 32) throw new Error("Encryption key must be 32 bytes (64 hex characters or base64)");
  return key;
}

/** `aad` identifies the owner, for example `sqkeys-owner|P3|<sqRef>|1`. The ciphertext carries the 16 byte tag at its end. */
export function sealSecret(key: Buffer, plaintext: Buffer, aad: string): { ciphertext: Buffer; nonce: Buffer } {
  const nonce = randomBytes(12);
  const cipher = createCipheriv(ALGORITHM, key, nonce);
  cipher.setAAD(Buffer.from(aad, "utf8"));
  const body = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  return { ciphertext: Buffer.concat([body, cipher.getAuthTag()]), nonce };
}

export function openSecret(key: Buffer, ciphertext: Buffer, nonce: Buffer, aad: string): Buffer {
  if (ciphertext.length < TAG_BYTES) throw new Error("Stored secret is corrupted");
  const decipher = createDecipheriv(ALGORITHM, key, nonce);
  decipher.setAAD(Buffer.from(aad, "utf8"));
  decipher.setAuthTag(ciphertext.subarray(ciphertext.length - TAG_BYTES));
  try {
    return Buffer.concat([decipher.update(ciphertext.subarray(0, ciphertext.length - TAG_BYTES)), decipher.final()]);
  } catch {
    throw new Error("Stored secret could not be decrypted");
  }
}
